evaluation.reference:
Algoritmo Buscar
  Dimension v[5] Como Entero;
  Para i <- 0 Hasta 4 Hacer
    Leer v[i];
  FinPara
  Definir searched Como Entero;
  Leer searched;
  Definir position Como Entero <- -1;
  Para i <- 0 Hasta 4 Hacer
    Si v[i] = searched Entonces
      position <- i;
      Salir;
    FinSi
  FinPara
  Escribir position;
FinAlgoritmo

